package com.fasterxml.jackson.core.base;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser.Feature;
import com.fasterxml.jackson.core.io.NumberInput;
import com.fasterxml.jackson.core.util.ByteArrayBuilder;
import com.fasterxml.jackson.core.util.VersionUtil;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.Method;
import java.math.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;

public class ParserMinimalBase__asciiBytes_TriageGen1Test {

    /**
     * Since the method is protected and static, we use reflection to access it 
     * for testing purposes in a standalone unit test.
     */
    private byte[] invokeAsciiBytes(String str) throws Exception {
        Method method = ParserMinimalBase.class.getDeclaredMethod("_asciiBytes", String.class);
        method.setAccessible(true);
        return (byte[]) method.invoke(null, str);
    }

    @Test
    public void testAsciiBytes_NormalString() throws Exception {
        String input = "Hello123";
        byte[] expected = input.getBytes(StandardCharsets.US_ASCII);
        byte[] actual = invokeAsciiBytes(input);
        assertArrayEquals("The byte array should match the ASCII representation of the string", expected, actual);
    }

    @Test
    public void testAsciiBytes_EmptyString() throws Exception {
        String input = "";
        byte[] expected = new byte[0];
        byte[] actual = invokeAsciiBytes(input);
        assertArrayEquals("Empty string should return an empty byte array", expected, actual);
    }

    @Test
    public void testAsciiBytes_SingleCharacter() throws Exception {
        String input = "A";
        byte[] expected = new byte[]{(byte) 'A'};
        byte[] actual = invokeAsciiBytes(input);
        assertArrayEquals("Single character string should return a byte array of length 1", expected, actual);
    }

    @Test
    public void testAsciiBytes_SpecialCharacters() throws Exception {
        // Testing characters within the standard ASCII range (0-127)
        String input = "!@#$%^&*()_+ \n\t";
        byte[] expected = input.getBytes(StandardCharsets.US_ASCII);
        byte[] actual = invokeAsciiBytes(input);
        assertArrayEquals("Should handle special ASCII characters correctly", expected, actual);
    }

    @Test
    public void testAsciiBytes_HighBitCharacters() throws Exception {
        // The method casts char to byte. For chars > 127, this results in narrowing primitive conversion.
        // '©' is U+00A9. (char)0xA9 as a byte is -87.
        String input = "©"; 
        byte[] actual = invokeAsciiBytes(input);

        assertEquals("Length should be 1", 1, actual.length);
        assertEquals("Byte value should be the lower 8 bits of the char", (byte) 0xA9, actual[0]);
    }

    @Test(expected = NullPointerException.class)
    public void testAsciiBytes_NullInput() throws Exception {
        invokeAsciiBytes(null);
    }
}
